root = os.path.join(os.path.dirname(__file__), '..', 'lib', 'l10n')
for idx, loc in ((0, 'en'), (1, 'ar')):
    out = {"@@locale": loc}
    for k, v in S.items():
        out[k] = v[idx]
    for k, (en, ar, ph) in P.items():
        out[k] = (en, ar)[idx]
        if loc == 'en':
            out['@' + k] = {"placeholders": {p: {"type": t} for p, t in ph.items()}}
    with open(os.path.join(root, f'app_{loc}.arb'), 'w', encoding='utf-8') as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
print(len(S) + len(P), 'keys')
